# -*- coding: utf-8 -*-
import json

FUNCTION_WORDS = {
    'le','la','les','un','une','des','du','de','l',
    'a','en','dans','sur','pour','par','avec','sans','sous','vers','chez',
    'et','ou','mais','donc','or','ni','car','que','si','comme','quand',
    'je','tu','il','elle','nous','vous','ils','elles',
    'me','te','se','lui','leur','eux',
    'ce','ceci','cela','ca','celui','celle','ceux','celles',
    'qui','quoi','dont','ou','lequel','laquelle','lesquels','lesquelles',
    'mon','ton','son','ma','ta','sa','mes','tes','ses','notre','votre','nos','vos','leurs',
    'etre','avoir','est','sont','ai','as','avons','avez','ont',
    'ne','pas','plus','jamais','rien','personne','aucun','y',
}

def is_function_word_entry(noun_id):
    words = noun_id.lower().replace("'", " ").replace("-", " ").split()
    if not words:
        return False
    return all(w in FUNCTION_WORDS for w in words)

def main():
    with open('s0-hits.json', 'r', encoding='utf-8') as f:
        s0 = json.load(f)
    with open('s1-nouns-with-offsets.json', 'r', encoding='utf-8') as f:
        s1 = json.load(f)

    # S0 check
    s0_seen = {}
    for chunk in s0.get('hitsByChunk', []):
        for hit in chunk.get('hits', []):
            nid = (hit.get('id') or '').strip()
            if nid and nid not in s0_seen:
                s0_seen[nid] = hit.get('surface', '')
    s0_bad = [(nid, surf) for nid, surf in s0_seen.items() if is_function_word_entry(nid)]

    # S1 check
    s1_seen = {}
    for n in s1.get('nouns', []):
        nid = (n.get('id') or '').strip()
        if nid and nid not in s1_seen:
            s1_seen[nid] = n.get('surface', '')
    s1_bad = [(nid, surf) for nid, surf in s1_seen.items() if is_function_word_entry(nid)]

    print(f"S0 unique nouns: {len(s0_seen)}")
    print(f"S0 pure-function-word entries: {len(s0_bad)}")
    for nid, surf in s0_bad[:50]:
        print(f"  - {surf!r} (id={nid!r})")

    print()
    print(f"S1 unique nouns: {len(s1_seen)}")
    print(f"S1 pure-function-word entries: {len(s1_bad)}")
    for nid, surf in s1_bad[:50]:
        print(f"  - {surf!r} (id={nid!r})")

if __name__ == '__main__':
    main()

import json

FUNCTION_WORDS = {
    'le', 'la', 'les', 'un', 'une', 'des', 'du', 'de', 'l',
    'à', 'en', 'dans', 'sur', 'pour', 'par', 'avec', 'sans', 'sous', 'vers', 'chez',
    'et', 'ou', 'mais', 'donc', 'or', 'ni', 'car', 'que', 'si', 'comme', 'quand',
    'je', 'tu', 'il', 'elle', 'nous', 'vous', 'ils', 'elles',
    'me', 'te', 'se', 'lui', 'leur', 'eux',
    'ce', 'ceci', 'cela', 'ça', 'celui', 'celle', 'ceux', 'celles',
    'qui', 'quoi', 'dont', 'où', 'lequel', 'laquelle', 'lesquels', 'lesquelles',
    'mon', 'ton', 'son', 'ma', 'ta', 'sa', 'mes', 'tes', 'ses', 'notre', 'votre', 'nos', 'vos', 'leurs',
    'est', 'sont', 'a', 'ont', 'ai', 'as', 'avons', 'avez',
    'ne', 'pas', 'plus', 'jamais', 'rien', 'personne', 'aucun', 'y',
}

APOSTROPHE_FUNCTION_PREFIXES = ("l'", "d'", "qu'", "n'", "s'", "c'", "m'", "t'", "j'")

def is_function_word(token: str) -> bool:
    t = token.lower().strip()
    if t in FUNCTION_WORDS:
        return True
    for p in APOSTROPHE_FUNCTION_PREFIXES:
        if t == p.rstrip("'") or t.startswith(p):
            return True
    return False

def check_entry(noun_id: str):
    words = noun_id.lower().replace("'", "' ").split()
    flags = [w for w in words if is_function_word(w)]
    return flags

def main():
    with open('s0-hits.json', 'r', encoding='utf-8') as f:
        s0_data = json.load(f)
    with open('s1-nouns-with-offsets.json', 'r', encoding='utf-8') as f:
        s1_data = json.load(f)

    print('=== S0 ===')
    s0_seen = {}
    for chunk in s0_data.get('hitsByChunk', []):
        for hit in chunk.get('hits', []):
            nid = (hit.get('id') or '').strip()
            surf = (hit.get('surface') or '').strip()
            if not nid or nid in s0_seen:
                continue
            flags = check_entry(nid)
            if flags:
                s0_seen[nid] = (surf, flags)

    print(f'S0 unique noun ids: total flagged = {len(s0_seen)}')
    for i, (nid, (surf, flags)) in enumerate(list(s0_seen.items())[:30], 1):
        print(f'{i}. surface="{surf}" id="{nid}" flagged_words={flags}')

    print('\n=== S1 ===')
    s1_seen = {}
    for entry in s1_data.get('nouns', []):
        nid = (entry.get('id') or '').strip()
        surf = (entry.get('surface') or '').strip()
        if not nid or nid in s1_seen:
            continue
        flags = check_entry(nid)
        if flags:
            s1_seen[nid] = (surf, flags)

    print(f'S1 unique noun ids: total flagged = {len(s1_seen)}')
    for i, (nid, (surf, flags)) in enumerate(list(s1_seen.items())[:30], 1):
        print(f'{i}. surface="{surf}" id="{nid}" flagged_words={flags}')

if __name__ == '__main__':
    main()

