def norm(s):
    return s.strip().lower().replace("'", "'")

def load(path):
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)

def main():
    s0 = load('s0-hits.json')
    s1 = load('s1-nouns-with-offsets.json')

    s0_ids = {}
    for chunk in s0.get('hitsByChunk', []):
